#[derive(Debug, Error)]
pub enum ParseError {
    #[error(transparent)]
    Lex(#[from] LexError),
    #[error("unbalanced RTF group ending at byte {0}")]
    UnbalancedGroup(usize),
    #[error("RTF group depth limit exceeded at byte {0}")]
    GroupDepthExceeded(usize),
    #[error("RTF destination data limit exceeded at byte {0}")]
    DestinationTooLarge(usize),
    #[error("output text character limit exceeded at byte {0}")]
    OutputTextTooLarge(usize),
    #[error("resource limit exceeded for {resource} at byte {offset}")]
    ResourceLimitExceeded { resource: String, offset: usize },
    #[error("malformed RTF input at byte {offset}: {reason}")]
    MalformedInput { reason: String, offset: usize },
    #[error("active content rejected: {feature} at byte {offset}")]
    ActiveContentRejected { feature: String, offset: usize },
    #[error("invalid RTF limits: {0}")]
    InvalidLimits(#[from] LimitValidationError),
    #[error("normalized document invariant failed: {0}")]
    ModelInvariant(#[from] crate::model::ModelInvariantError),
}

#[derive(Debug, Clone)]
pub struct ParseOutput {
    pub document: Document,
    pub diagnostics: Vec<Diagnostic>,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum CharacterSelector {
    Unspecified,
    LowAnsi,
    HighAnsi,
    DoubleByte,
}

fn is_word_double_byte_character(ch: char) -> bool {
    matches!(
        u32::from(ch),
        0x1100..=0x11ff
            | 0x2e80..=0x4dbf
            | 0x4e00..=0x9fff
            | 0xa960..=0xa97f
            | 0xac00..=0xd7ff
            | 0xf900..=0xfaff
            | 0xfe30..=0xfe4f
            | 0xff00..=0xffef
            | 0x20000..=0x2fa1f
    )
}

fn destination_emits_visible_text(destination: Destination) -> bool {
    matches!(
        destination,
        Destination::Body
            | Destination::ListText
            | Destination::Header
            | Destination::FirstPageHeader
            | Destination::EvenPageHeader
            | Destination::Footer
            | Destination::FirstPageFooter
            | Destination::EvenPageFooter
            | Destination::ShapeText
            | Destination::Footnote
            | Destination::Endnote
            | Destination::FootnoteSeparator
            | Destination::FootnoteContinuationSeparator
            | Destination::EndnoteSeparator
            | Destination::EndnoteContinuationSeparator
    )
}

