    fn set_picture_kind(&mut self, kind: PictureKind) {
        if let Some(picture) = self.current_picture.as_mut() {
            picture.kind = kind;
        }
    }

    fn skip_picture_blip_uid(&mut self, offset: usize) {
        if let Some(picture) = self.current_picture.as_mut() {
            if picture.blip_uid_hex_nibbles_remaining > 0 {
                self.diagnostics.push(Diagnostic::warning(
                    "overlapping picture blip UID metadata replaced before previous UID completed",
                    Some(offset),
                ));
            }
            picture.blip_uid_hex_nibbles_remaining = 32;
        }
    }

    fn set_picture_blip_units_per_inch(&mut self, value: Option<i32>, offset: usize) {
        let value = value.unwrap_or(0);
        if value <= 0 {
            self.diagnostics.push(Diagnostic::warning(
                format!("picture units-per-inch metadata ignored because value {value} is invalid"),
                Some(offset),
            ));
            return;
        }

        const MAX_PASSIVE_PICTURE_UNITS_PER_INCH: i32 = 9_600;
        let normalized = value.min(MAX_PASSIVE_PICTURE_UNITS_PER_INCH);
        if normalized != value {
            self.diagnostics.push(Diagnostic::warning(
                format!("picture units-per-inch metadata clamped from {value} to {normalized}"),
                Some(offset),
            ));
        }
        if let Some(picture) = self.current_picture.as_mut() {
            picture.blip_units_per_inch = Some(normalized as u32);
        }
    }

    fn set_picture_windows_bitmap_planes(&mut self, value: Option<i32>, offset: usize) {
        let value = value.unwrap_or(0);
        if value <= 0 {
            self.diagnostics.push(Diagnostic::warning(
                format!("Windows bitmap planes metadata ignored because value {value} is invalid"),
                Some(offset),
            ));
            return;
        }
        let clamped = value.min(4);
        if clamped != value {
            self.diagnostics.push(Diagnostic::warning(
                format!("Windows bitmap planes metadata clamped from {value} to {clamped}"),
                Some(offset),
            ));
        }
        if let Some(picture) = self.current_picture.as_mut() {
            picture.windows_bitmap_planes = Some(clamped as u16);
        }
    }

