fn push_form_dropdown_entry(
    entries: &mut Vec<String>,
    entry: &str,
    limit: usize,
    offset: usize,
) -> Result<(), ParseError> {
    let entry = entry.trim_end();
    if entry.is_empty() || entry.chars().any(|ch| ch.is_control()) {
        return Ok(());
    }
    if entries.len() >= limit {
        return Err(ParseError::ResourceLimitExceeded {
            resource: "form dropdown entries".to_string(),
            offset,
        });
    }
    entries.push(entry.to_string());
    Ok(())
}

fn merge_child_form_dropdown_entries(
    target: &mut Vec<String>,
    child: &[String],
    limit: usize,
    offset: usize,
) -> Result<(), ParseError> {
    let additions = if child.len() >= target.len() && child.starts_with(target.as_slice()) {
        &child[target.len()..]
    } else {
        child
    };
    for entry in additions {
        push_form_dropdown_entry(target, entry, limit, offset)?;
    }
    Ok(())
}

fn field_sequence_instruction(instruction: &str) -> Option<FieldSequenceInstruction> {
    let rest = field_rest_after_name(instruction)?.trim_start();
    if rest.is_empty() || rest.starts_with('\\') {
        return None;
    }

    let text = if rest.starts_with('"') {
        field_quoted_prefix(rest)?
    } else {
        let end = rest
            .char_indices()
            .find_map(|(index, ch)| (ch.is_whitespace() || ch == '\\').then_some(index))
            .unwrap_or(rest.len());
        rest[..end].to_string()
    };
    let text = text.trim().to_string();
    if text.is_empty() || text.chars().any(|ch| ch.is_control()) || contains_internal_marker(&text)
    {
        return None;
    }

    let mut rest = skip_field_argument(rest).unwrap_or("");
    let mut repeat_current = false;
    let mut hidden = false;
    let mut reset_value = None;
    while let Some((switch, after_switch)) = next_field_switch(rest) {
        rest = after_switch;
        match switch {
            'c' => repeat_current = true,
            'h' => hidden = true,
            'n' => repeat_current = false,
            'r' => {
                let (value, after_value) = field_switch_i32(rest);
                reset_value = value;
                rest = after_value;
            }
            _ => {}
        }
    }

    Some(FieldSequenceInstruction {
        name: text,
        repeat_current,
        hidden,
        reset_value,
    })
}

fn field_list_number_instruction(instruction: &str) -> Option<FieldListNumberInstruction> {
    let rest = field_rest_after_name(instruction)?.trim_start();
    let (name, mut rest) = if rest.is_empty() || rest.starts_with('\\') {
        (String::new(), rest)
    } else if rest.starts_with('"') {
        let name = field_quoted_prefix(rest)?.trim().to_string();
        (name, skip_field_argument(rest).unwrap_or(""))
    } else {
        let end = rest
            .char_indices()
            .find_map(|(index, ch)| (ch.is_whitespace() || ch == '\\').then_some(index))
            .unwrap_or(rest.len());
        (rest[..end].trim().to_string(), &rest[end..])
    };
    if name.chars().any(|ch| ch.is_control()) || contains_internal_marker(&name) {
        return None;
    }

    let mut level = 1;
    let mut reset_value = None;
    while let Some((switch, after_switch)) = next_field_switch(rest) {
        rest = after_switch;
        match switch {
            'l' => {
                let (value, after_value) = field_switch_i32(rest);
                if let Some(value) = value
                    && value > 0
                {
                    level = value;
                }
                rest = after_value;
            }
            's' => {
                let (value, after_value) = field_switch_i32(rest);
                reset_value = value;
                rest = after_value;
            }
            _ => {}
        }
    }

    Some(FieldListNumberInstruction {
        name,
        level,
        reset_value,
    })
}

fn field_rest_after_name(instruction: &str) -> Option<&str> {
    let instruction = instruction.trim_start();
    let name_len = instruction
        .chars()
        .take_while(|ch| ch.is_ascii_alphabetic())
        .map(char::len_utf8)
        .sum::<usize>();
    (name_len > 0).then_some(&instruction[name_len..])
}

fn field_quoted_prefix(input: &str) -> Option<String> {
    let mut rest = input.chars();
    if rest.next()? != '"' {
        return None;
    }
    let mut output = String::new();
    let mut escaped = false;
    for ch in rest {
        if escaped {
            match ch {
                '"' | '\\' => output.push(ch),
                _ => {
                    output.push('\\');
                    output.push(ch);
                }
            }
            escaped = false;
        } else if ch == '\\' {
            escaped = true;
        } else if ch == '"' {
            return Some(output);
        } else {
            output.push(ch);
        }
    }
    None
}

fn skip_field_argument(input: &str) -> Option<&str> {
    let input = input.trim_start();
    if input.is_empty() {
        return None;
    }

    if input.starts_with('"') {
        let mut escaped = false;
        for (index, ch) in input.char_indices().skip(1) {
            if escaped {
                escaped = false;
            } else if ch == '\\' {
                escaped = true;
            } else if ch == '"' {
                return Some(&input[index + ch.len_utf8()..]);
            }
        }
        return None;
    }

    let end = input
        .char_indices()
        .find_map(|(index, ch)| ch.is_whitespace().then_some(index))
        .unwrap_or(input.len());
    Some(&input[end..])
}

fn next_field_switch(input: &str) -> Option<(char, &str)> {
    let input = input.trim_start();
    let rest = input.strip_prefix('\\')?;
    let mut chars = rest.char_indices();
    let (_, switch) = chars.next()?;
    let switch_end = switch.len_utf8();
    Some((switch.to_ascii_lowercase(), &rest[switch_end..]))
}

fn field_switch_i32(input: &str) -> (Option<i32>, &str) {
    let input = input.trim_start();
    let mut end = 0;
    for (index, ch) in input.char_indices() {
        if index == 0 && ch == '-' {
            end = ch.len_utf8();
            continue;
        }
        if !ch.is_ascii_digit() {
            break;
        }
        end = index + ch.len_utf8();
    }

    if end == 0 || input[..end].chars().all(|ch| ch == '-') {
        return (None, input);
    }

    let value = input[..end].parse::<i32>().ok();
    (value, &input[end..])
}

fn field_switch_i32_value(instruction: &str, target_switch: char) -> Option<i32> {
    let target_switch = target_switch.to_ascii_lowercase();
    let mut in_quote = false;
    let mut escaped = false;

    for (index, ch) in instruction.char_indices() {
        if in_quote {
            if escaped {
                escaped = false;
            } else if ch == '\\' {
                escaped = true;
            } else if ch == '"' {
                in_quote = false;
            }
            continue;
        }

        if ch == '"' {
            in_quote = true;
            continue;
        }

        if ch == '\\' {
            let after_slash = index + ch.len_utf8();
            let Some(switch) = instruction[after_slash..].chars().next() else {
                break;
            };
            let switch_end = after_slash + switch.len_utf8();
            if switch.to_ascii_lowercase() == target_switch {
                let (value, _) = field_switch_i32(&instruction[switch_end..]);
                return value;
            }
        }
    }
    None
}

fn field_switch_string_value(instruction: &str, switch: u8) -> Option<String> {
    let bytes = instruction.as_bytes();
    let switch = switch.to_ascii_lowercase();
    let mut in_quote = false;
    let mut escaped = false;

    for (index, ch) in instruction.char_indices() {
        if in_quote {
            if escaped {
                escaped = false;
            } else if ch == '\\' {
                escaped = true;
            } else if ch == '"' {
                in_quote = false;
            }
            continue;
        }

        if ch == '"' {
            in_quote = true;
            continue;
        }

        if ch == '\\' {
            let after_slash = index + ch.len_utf8();
            let Some(candidate) = instruction[after_slash..].chars().next() else {
                break;
            };
            if !candidate.is_ascii() || candidate.to_ascii_lowercase() as u8 != switch {
                continue;
            }

            let mut value_start = after_slash + candidate.len_utf8();
            if value_start < bytes.len()
                && !bytes[value_start].is_ascii_whitespace()
                && bytes[value_start] != b'"'
            {
                continue;
            }
            while value_start < bytes.len() && bytes[value_start].is_ascii_whitespace() {
                value_start += 1;
            }
            if let Some(value) = field_switch_argument_value(&instruction[value_start..]) {
                return Some(value);
            }
        }
    }
    None
}

fn field_has_flag_switch(instruction: &str, target: char) -> bool {
    let mut in_quote = false;
    let mut escaped = false;
    for (index, ch) in instruction.char_indices() {
        if in_quote {
            if escaped {
                escaped = false;
            } else if ch == '\\' {
                escaped = true;
            } else if ch == '"' {
                in_quote = false;
            }
            continue;
        }
        if ch == '"' {
            in_quote = true;
            continue;
        }
        if ch != '\\' {
            continue;
        }
        let after_slash = index + ch.len_utf8();
        let mut chars = instruction[after_slash..].chars();
        let Some(candidate) = chars.next() else {
            break;
        };
        if candidate.eq_ignore_ascii_case(&target) && chars.next().is_none_or(char::is_whitespace) {
            return true;
        }
    }
    false
}

fn field_switch_character_value(instruction: &str, target: char) -> Option<char> {
    let mut in_quote = false;
    let mut escaped = false;
    for (index, ch) in instruction.char_indices() {
        if in_quote {
            if escaped {
                escaped = false;
            } else if ch == '\\' {
                escaped = true;
            } else if ch == '"' {
                in_quote = false;
            }
            continue;
        }
        if ch == '"' {
            in_quote = true;
            continue;
        }
        if ch != '\\' {
            continue;
        }
        let after_slash = index + ch.len_utf8();
        let mut chars = instruction[after_slash..].chars();
        let Some(candidate) = chars.next() else {
            break;
        };
        if !candidate.eq_ignore_ascii_case(&target) {
            continue;
        }
        let value_start = after_slash + candidate.len_utf8();
        let value = instruction[value_start..].trim_start();
        let value = if value.starts_with('"') {
            field_quoted_prefix(value)?
        } else {
            value.to_string()
        };
        return value.chars().next().filter(|ch| {
            !ch.is_control()
                && !matches!(ch, '\\' | '{' | '}' | '\u{fffd}')
                && !contains_internal_marker(&ch.to_string())
        });
    }
    None
}

fn field_switch_argument_value(input: &str) -> Option<String> {
    let value = if input.starts_with('"') {
        field_quoted_prefix(input)?
    } else {
        let end = input
            .char_indices()
            .find_map(|(index, ch)| ch.is_whitespace().then_some(index))
            .unwrap_or(input.len());
        if end == 0 {
            return None;
        }
        input[..end].to_string()
    };
    let value = value.trim();
    if value.is_empty()
        || value.chars().count() > MAX_PASSIVE_FIELD_SWITCH_VALUE_CHARS
        || value
            .chars()
            .any(|ch| ch.is_control() || matches!(ch, '\\' | '{' | '}') || ch == '\u{fffd}')
        || contains_internal_marker(value)
    {
        return None;
    }
    Some(value.to_string())
}

fn is_internal_marker(text: &str) -> bool {
    matches!(
        text,
        PAGE_NUMBER_MARKER
            | TOTAL_PAGES_MARKER
            | SECTION_NUMBER_MARKER
            | SECTION_PAGES_MARKER
            | DOCUMENT_WORDS_MARKER
            | DOCUMENT_CHARS_MARKER
            | DOCUMENT_CHARS_WITH_SPACES_MARKER
            | PASSIVE_ADVANCE_MARKER
            | PASSIVE_MATH_FRACTION_RULE_MARKER
            | PASSIVE_MATH_STACK_ANCHOR_MARKER
            | PENDING_NOTE_REFERENCE_MARKER
            | FOOTNOTE_REFERENCE_MARKER
            | FOOTNOTE_REFERENCE_MARKER_END
            | ENDNOTE_REFERENCE_MARKER
            | ENDNOTE_REFERENCE_MARKER_END
    ) || is_bookmark_page_marker(text)
}

fn contains_internal_marker(text: &str) -> bool {
    text.contains(PAGE_NUMBER_MARKER)
        || text.contains(TOTAL_PAGES_MARKER)
        || text.contains(SECTION_NUMBER_MARKER)
        || text.contains(SECTION_PAGES_MARKER)
        || text.contains(DOCUMENT_WORDS_MARKER)
        || text.contains(DOCUMENT_CHARS_MARKER)
        || text.contains(DOCUMENT_CHARS_WITH_SPACES_MARKER)
        || text.contains(PASSIVE_ADVANCE_MARKER)
        || text.contains(PASSIVE_MATH_FRACTION_RULE_MARKER)
        || text.contains(PASSIVE_MATH_STACK_ANCHOR_MARKER)
        || text.contains(PENDING_NOTE_REFERENCE_MARKER)
        || text.contains(FOOTNOTE_REFERENCE_MARKER)
        || text.contains(FOOTNOTE_REFERENCE_MARKER_END)
        || text.contains(ENDNOTE_REFERENCE_MARKER)
        || text.contains(ENDNOTE_REFERENCE_MARKER_END)
        || text.contains(BOOKMARK_PAGE_ANCHOR_MARKER)
        || text.contains(BOOKMARK_PAGE_REF_MARKER)
        || text.contains(BOOKMARK_PAGE_MARKER_END)
}

fn sanitize_internal_markers(text: &str) -> String {
    text.replace(PAGE_NUMBER_MARKER, "\u{fffd}")
        .replace(TOTAL_PAGES_MARKER, "\u{fffd}")
        .replace(SECTION_NUMBER_MARKER, "\u{fffd}")
        .replace(SECTION_PAGES_MARKER, "\u{fffd}")
        .replace(DOCUMENT_WORDS_MARKER, "\u{fffd}")
        .replace(DOCUMENT_CHARS_MARKER, "\u{fffd}")
        .replace(DOCUMENT_CHARS_WITH_SPACES_MARKER, "\u{fffd}")
        .replace(PASSIVE_ADVANCE_MARKER, "\u{fffd}")
        .replace(PASSIVE_MATH_FRACTION_RULE_MARKER, "\u{fffd}")
        .replace(PASSIVE_MATH_STACK_ANCHOR_MARKER, "\u{fffd}")
        .replace(PENDING_NOTE_REFERENCE_MARKER, "\u{fffd}")
        .replace(FOOTNOTE_REFERENCE_MARKER, "\u{fffd}")
        .replace(FOOTNOTE_REFERENCE_MARKER_END, "\u{fffd}")
        .replace(ENDNOTE_REFERENCE_MARKER, "\u{fffd}")
        .replace(ENDNOTE_REFERENCE_MARKER_END, "\u{fffd}")
        .replace(BOOKMARK_PAGE_ANCHOR_MARKER, "\u{fffd}")
        .replace(BOOKMARK_PAGE_REF_MARKER, "\u{fffd}")
        .replace(BOOKMARK_PAGE_MARKER_END, "\u{fffd}")
}

fn is_bookmark_page_marker(text: &str) -> bool {
    parse_bookmark_page_marker_id(text, BOOKMARK_PAGE_ANCHOR_MARKER).is_some()
        || parse_bookmark_page_marker_id(text, BOOKMARK_PAGE_REF_MARKER).is_some()
}

fn contains_bookmark_page_marker(text: &str) -> bool {
    text.contains(BOOKMARK_PAGE_ANCHOR_MARKER)
        || text.contains(BOOKMARK_PAGE_REF_MARKER)
        || text.contains(BOOKMARK_PAGE_MARKER_END)
}

fn strip_bookmark_page_markers(text: &str) -> Option<String> {
    let mut output = String::with_capacity(text.len());
    let mut search_start = 0;
    loop {
        let anchor_start = text[search_start..]
            .find(BOOKMARK_PAGE_ANCHOR_MARKER)
            .map(|relative| (search_start + relative, BOOKMARK_PAGE_ANCHOR_MARKER));
        let ref_start = text[search_start..]
            .find(BOOKMARK_PAGE_REF_MARKER)
            .map(|relative| (search_start + relative, BOOKMARK_PAGE_REF_MARKER));
        let Some((marker_start, prefix)) = [anchor_start, ref_start]
            .into_iter()
            .flatten()
            .min_by_key(|(start, _)| *start)
        else {
            output.push_str(&text[search_start..]);
            return Some(output);
        };
        let id_start = marker_start + prefix.len();
        let marker_end_relative = text[id_start..].find(BOOKMARK_PAGE_MARKER_END)?;
        let marker_end = id_start + marker_end_relative + BOOKMARK_PAGE_MARKER_END.len();
        parse_bookmark_page_marker_id(&text[marker_start..marker_end], prefix)?;
        output.push_str(&text[search_start..marker_start]);
        search_start = marker_end;
    }
}

fn parse_bookmark_page_marker_id(text: &str, prefix: &str) -> Option<usize> {
    let rest = text.strip_prefix(prefix)?;
    let id = rest.strip_suffix(BOOKMARK_PAGE_MARKER_END)?;
    (!id.is_empty() && id.chars().all(|ch| ch.is_ascii_digit()))
        .then(|| id.parse::<usize>().ok())?
}

fn format_list_counter(value: i32, format: ListNumberFormat) -> String {
    match format {
        ListNumberFormat::Decimal | ListNumberFormat::Other | ListNumberFormat::Bullet => {
            value.to_string()
        }
        ListNumberFormat::UpperRoman => format_roman_counter(value, false),
        ListNumberFormat::LowerRoman => format_roman_counter(value, true),
        ListNumberFormat::UpperLetter => format_alpha_counter(value, false),
        ListNumberFormat::LowerLetter => format_alpha_counter(value, true),
        ListNumberFormat::Ordinal => format_ordinal_counter(value),
        ListNumberFormat::CardinalText => {
            format_cardinal_text_counter(value).unwrap_or_else(|| value.to_string())
        }
        ListNumberFormat::OrdinalText => {
            format_ordinal_text_counter(value).unwrap_or_else(|| value.to_string())
        }
        ListNumberFormat::DecimalLeadingZero(width) => {
            format_zero_padded_decimal_counter(value, width)
        }
    }
}

fn format_note_number(start: i32, sequence: usize, format: PageNumberFormat) -> String {
    let sequence_offset = sequence.saturating_sub(1).min(i32::MAX as usize) as i32;
    let value = start.max(1).saturating_add(sequence_offset);
    match format {
        PageNumberFormat::Decimal => value.to_string(),
        PageNumberFormat::UpperRoman => format_roman_counter(value, false),
        PageNumberFormat::LowerRoman => format_roman_counter(value, true),
        PageNumberFormat::UpperLetter => format_alpha_counter(value, false),
        PageNumberFormat::LowerLetter => format_alpha_counter(value, true),
    }
}

fn list_level_start_at(
    list_override: &ListOverride,
    level: &ListLevelDefinition,
    level_index: usize,
) -> i32 {
    list_override
        .level_overrides
        .iter()
        .find(|level_override| level_override.level_index == level_index)
        .and_then(|level_override| level_override.start_at)
        .unwrap_or(level.start_at)
}

fn has_list_level_placeholders(template: &str) -> bool {
    template
        .chars()
        .any(|ch| list_level_placeholder_index(ch).is_some())
}

fn list_level_placeholder_index(ch: char) -> Option<usize> {
    if ch <= '\u{8}' {
        Some(ch as usize)
    } else {
        None
    }
}

fn list_level_follow_text(follow: ListLevelFollow) -> &'static str {
    match follow {
        ListLevelFollow::Tab => "\t",
        ListLevelFollow::Space => " ",
        ListLevelFollow::Nothing => "",
    }
}

fn format_roman_counter(value: i32, lowercase: bool) -> String {
    if !(1..=3999).contains(&value) {
        return value.to_string();
    }
    let mut remaining = value;
    let mut output = String::new();
    for (unit, symbol) in [
        (1000, "M"),
        (900, "CM"),
        (500, "D"),
        (400, "CD"),
        (100, "C"),
        (90, "XC"),
        (50, "L"),
        (40, "XL"),
        (10, "X"),
        (9, "IX"),
        (5, "V"),
        (4, "IV"),
        (1, "I"),
    ] {
        while remaining >= unit {
            output.push_str(symbol);
            remaining -= unit;
        }
    }
    if lowercase {
        output.to_ascii_lowercase()
    } else {
        output
    }
}

fn format_alpha_counter(value: i32, lowercase: bool) -> String {
    if value <= 0 {
        return value.to_string();
    }
    let mut value = value as u32;
    let mut chars = Vec::new();
    while value > 0 {
        value -= 1;
        let ch = (b'A' + (value % 26) as u8) as char;
        chars.push(if lowercase {
            ch.to_ascii_lowercase()
        } else {
            ch
        });
        value /= 26;
    }
    chars.iter().rev().collect()
}

fn format_ordinal_counter(value: i32) -> String {
    if value <= 0 {
        return value.to_string();
    }

    let suffix = match value % 100 {
        11..=13 => "th",
        _ => match value % 10 {
            1 => "st",
            2 => "nd",
            3 => "rd",
            _ => "th",
        },
    };
    format!("{value}{suffix}")
}

fn format_cardinal_text_counter(value: i32) -> Option<String> {
    if !(0..=999).contains(&value) {
        return None;
    }
    Some(cardinal_text_under_1000(value as usize))
}

fn format_ordinal_text_counter(value: i32) -> Option<String> {
    if !(0..=999).contains(&value) {
        return None;
    }
    Some(ordinal_text_under_1000(value as usize))
}

fn format_dollar_text_counter(value: i32) -> Option<String> {
    if !(0..=999).contains(&value) {
        return None;
    }
    Some(format!(
        "{} and 00/100",
        cardinal_text_under_1000(value as usize)
    ))
}

fn cardinal_text_under_1000(value: usize) -> String {
    if value < 20 {
        return cardinal_text_under_20(value).to_string();
    }
    if value < 100 {
        return cardinal_tens_text(value);
    }

    let hundreds = value / 100;
    let remainder = value % 100;
    let mut output = format!("{} hundred", cardinal_text_under_20(hundreds));
    if remainder > 0 {
        output.push(' ');
        output.push_str(&cardinal_text_under_1000(remainder));
    }
    output
}

fn ordinal_text_under_1000(value: usize) -> String {
    if value < 20 {
        return ordinal_text_under_20(value).to_string();
    }
    if value < 100 {
        return ordinal_tens_text(value);
    }

    let hundreds = value / 100;
    let remainder = value % 100;
    if remainder == 0 {
        return format!("{} hundredth", cardinal_text_under_20(hundreds));
    }
    format!(
        "{} hundred {}",
        cardinal_text_under_20(hundreds),
        ordinal_text_under_1000(remainder)
    )
}

fn cardinal_tens_text(value: usize) -> String {
    let tens = value / 10;
    let remainder = value % 10;
    let prefix = cardinal_tens_word(tens);
    if remainder == 0 {
        prefix.to_string()
    } else {
        format!("{prefix}-{}", cardinal_text_under_20(remainder))
    }
}

fn ordinal_tens_text(value: usize) -> String {
    let tens = value / 10;
    let remainder = value % 10;
    if remainder == 0 {
        return ordinal_tens_word(tens).to_string();
    }
    format!(
        "{}-{}",
        cardinal_tens_word(tens),
        ordinal_text_under_20(remainder)
    )
}

fn cardinal_text_under_20(value: usize) -> &'static str {
    match value {
        0 => "zero",
        1 => "one",
        2 => "two",
        3 => "three",
        4 => "four",
        5 => "five",
        6 => "six",
        7 => "seven",
        8 => "eight",
        9 => "nine",
        10 => "ten",
        11 => "eleven",
        12 => "twelve",
        13 => "thirteen",
        14 => "fourteen",
        15 => "fifteen",
        16 => "sixteen",
        17 => "seventeen",
        18 => "eighteen",
        19 => "nineteen",
        _ => "",
    }
}

fn ordinal_text_under_20(value: usize) -> &'static str {
    match value {
        0 => "zeroth",
        1 => "first",
        2 => "second",
        3 => "third",
        4 => "fourth",
        5 => "fifth",
        6 => "sixth",
        7 => "seventh",
        8 => "eighth",
        9 => "ninth",
        10 => "tenth",
        11 => "eleventh",
        12 => "twelfth",
        13 => "thirteenth",
        14 => "fourteenth",
        15 => "fifteenth",
        16 => "sixteenth",
        17 => "seventeenth",
        18 => "eighteenth",
        19 => "nineteenth",
        _ => "",
    }
}

fn cardinal_tens_word(tens: usize) -> &'static str {
    match tens {
        2 => "twenty",
        3 => "thirty",
        4 => "forty",
        5 => "fifty",
        6 => "sixty",
        7 => "seventy",
        8 => "eighty",
        9 => "ninety",
        _ => "",
    }
}

fn ordinal_tens_word(tens: usize) -> &'static str {
    match tens {
        2 => "twentieth",
        3 => "thirtieth",
        4 => "fortieth",
        5 => "fiftieth",
        6 => "sixtieth",
        7 => "seventieth",
        8 => "eightieth",
        9 => "ninetieth",
        _ => "",
    }
}

fn format_zero_padded_decimal_counter(value: i32, width: usize) -> String {
    if value < 0 {
        return value.to_string();
    }
    format!("{value:0width$}")
}

fn passive_math_phantom_text_width_twips(text: &str, style: &CharacterStyle) -> i32 {
    let width_milli_em = text.chars().fold(0_i64, |width, ch| {
        let char_width = if ch.is_control() {
            0
        } else if ch.is_whitespace() {
            250
        } else if matches!(ch, 'i' | 'l' | 'I' | 'j' | 't' | 'f') {
            278
        } else if matches!(ch, 'm' | 'w' | 'M' | 'W') {
            833
        } else if ch.is_ascii_uppercase() {
            667
        } else if ch.is_ascii_lowercase() || ch.is_ascii_digit() {
            500
        } else if ch.is_ascii_punctuation() {
            333
        } else {
            1_000
        };
        width.saturating_add(char_width)
    });
    let width_twips = (style.font_size_points() * 20.0) * (width_milli_em as f32 / 1_000.0);
    width_twips.round().clamp(0.0, i32::MAX as f32) as i32
}

fn push_text_to_paragraph(
    paragraph: &mut Paragraph,
    text: &str,
    paragraph_style: &ParagraphStyle,
    character_style: &CharacterStyle,
) {
    if paragraph.style != *paragraph_style && paragraph.runs.is_empty() {
        paragraph.style = paragraph_style.clone();
    }

    if let Some(last) = paragraph.runs.last_mut()
        && last.style == *character_style
        && !contains_bookmark_page_marker(text)
        && !contains_bookmark_page_marker(&last.text)
    {
        last.text.push_str(text);
        return;
    }

    paragraph.runs.push(Run {
        text: text.to_string(),
        style: character_style.clone(),
    });
}

fn paragraph_plain_text(paragraph: &Paragraph) -> Option<String> {
    let mut text = String::new();
    for run in &paragraph.runs {
        if run.style.hidden {
            continue;
        }
        text.push_str(&run.text);
    }
    let text = text.trim().to_string();
    (!text.is_empty()).then_some(text)
}

fn paragraph_style_ref_text(paragraph: &Paragraph) -> Option<String> {
    let text = paragraph_plain_text(paragraph)?;
    let text = if paragraph_style_ref_number_text(paragraph).is_some() {
        text.split_once('\t').map(|(_, body)| body).unwrap_or(&text)
    } else {
        &text
    };
    let text = text.trim().to_string();
    (!text.is_empty()).then_some(text)
}

fn paragraph_style_ref_number_text(paragraph: &Paragraph) -> Option<String> {
    let mut text = String::new();
    for run in &paragraph.runs {
        if run.style.hidden {
            continue;
        }
        text.push_str(&run.text);
    }
    let (marker, _) = text.split_once('\t')?;
    let marker = marker.trim().to_string();
    if marker.is_empty()
        || marker.chars().count() > MAX_PASSIVE_FIELD_FORMAT_TEXT_CHARS
        || marker.chars().any(|ch| ch.is_control())
        || contains_internal_marker(&marker)
    {
        return None;
    }
    Some(marker)
}

fn trim_style_ref_trailing_number_delimiters(text: &str) -> Option<String> {
    let trimmed = text
        .trim_end_matches(|ch: char| {
            matches!(ch, '.' | ')' | ':' | '-' | '\u{2013}' | '\u{2014}') || ch.is_whitespace()
        })
        .trim()
        .to_string();
    (!trimmed.is_empty()).then_some(trimmed)
}

fn word_compatible_style_ref_number_text(text: &str, _mode: StyleRefNumberMode) -> Option<String> {
    trim_style_ref_trailing_number_delimiters(text)
}

fn push_text_to_runs(runs: &mut Vec<Run>, text: &str, character_style: &CharacterStyle) {
    if let Some(last) = runs.last_mut()
        && last.style == *character_style
    {
        last.text.push_str(text);
        return;
    }

    runs.push(Run {
        text: text.to_string(),
        style: character_style.clone(),
    });
}

fn replace_last_pending_note_marker_in_block(block: &mut Block, replacement: &str) -> bool {
    match block {
        Block::Paragraph(paragraph) => {
            replace_last_pending_note_marker_in_paragraph(paragraph, replacement)
        }
        Block::Table(table) => {
            for row in table.rows.iter_mut().rev() {
                for cell in row.cells.iter_mut().rev() {
                    for paragraph in cell.paragraphs.iter_mut().rev() {
                        if replace_last_pending_note_marker_in_paragraph(paragraph, replacement) {
                            return true;
                        }
                    }
                }
            }
            false
        }
        _ => false,
    }
}

fn replace_last_pending_note_marker_in_paragraph(
    paragraph: &mut Paragraph,
    replacement: &str,
) -> bool {
    replace_last_note_marker_in_paragraph(paragraph, PENDING_NOTE_REFERENCE_MARKER, replacement)
}

fn replace_last_note_marker_in_paragraph(
    paragraph: &mut Paragraph,
    marker: &str,
    replacement: &str,
) -> bool {
    for run in paragraph.runs.iter_mut().rev() {
        if run.text.contains(marker) {
            run.text = replace_last_marker(&run.text, marker, replacement);
            return true;
        }
    }
    false
}

fn replace_last_pending_note_marker_in_paragraphs(
    paragraphs: &mut [Paragraph],
    replacement: &str,
) -> bool {
    for paragraph in paragraphs.iter_mut().rev() {
        if replace_last_pending_note_marker_in_paragraph(paragraph, replacement) {
            return true;
        }
    }
    false
}

fn replace_last_marker(text: &str, marker: &str, replacement: &str) -> String {
    let Some(idx) = text.rfind(marker) else {
        return text.to_string();
    };
    let mut output = String::with_capacity(text.len() + replacement.len());
    output.push_str(&text[..idx]);
    output.push_str(replacement);
    output.push_str(&text[idx + marker.len()..]);
    output
}

fn replace_all_pending_note_markers_in_block(block: &mut Block, replacement: &str) {
    match block {
        Block::Paragraph(paragraph) => {
            replace_all_pending_note_markers_in_paragraph(paragraph, replacement);
        }
        Block::Table(table) => {
            for row in &mut table.rows {
                for cell in &mut row.cells {
                    for paragraph in &mut cell.paragraphs {
                        replace_all_pending_note_markers_in_paragraph(paragraph, replacement);
                    }
                }
            }
        }
        _ => {}
    }
}

fn replace_all_pending_note_markers_in_paragraph(paragraph: &mut Paragraph, replacement: &str) {
    for run in &mut paragraph.runs {
        if run.text.contains(PENDING_NOTE_REFERENCE_MARKER) {
            run.text = run.text.replace(PENDING_NOTE_REFERENCE_MARKER, replacement);
        }
    }
}

fn replace_all_pending_note_markers_in_paragraphs(paragraphs: &mut [Paragraph], replacement: &str) {
    for paragraph in paragraphs {
        replace_all_pending_note_markers_in_paragraph(paragraph, replacement);
    }
}

fn normalize_list_level_template(template: &str) -> String {
    let mut chars = template.chars().collect::<Vec<_>>();
    if let Some(length) = chars.first().and_then(|ch| {
        (ch.is_control() && *ch != '\0')
            .then_some((*ch as usize).min(chars.len().saturating_sub(1)))
    }) {
        return chars.into_iter().skip(1).take(length).collect();
    }
    while chars.last().is_some_and(|ch| *ch == ';') {
        chars.pop();
    }
    chars.into_iter().collect()
}

fn normalized_page_settings(mut page: PageSettings) -> PageSettings {
    if page.landscape && page.width_twips < page.height_twips {
        std::mem::swap(&mut page.width_twips, &mut page.height_twips);
    }
    page.column_count = page.column_count.max(1);
    page.column_widths_twips.truncate(page.column_count);
    page.column_gaps_twips.truncate(page.column_count);
    page
}

fn normalized_preferred_table_width_twips(
    preferred_width: PreferredTableWidth,
    page_content_width_twips: i32,
    max_width_twips: i32,
) -> Option<i32> {
    let value = preferred_width.value?.max(0);
    let width = match preferred_width.unit {
        PreferredTableWidthUnit::Twips => value,
        PreferredTableWidthUnit::FiftiethsPercent => {
            let content_width = i64::from(page_content_width_twips.max(1));
            let scaled = content_width.saturating_mul(i64::from(value)) / 5_000;
            i32::try_from(scaled).unwrap_or(i32::MAX)
        }
        PreferredTableWidthUnit::Auto => return None,
    };
    Some(width.clamp(1, max_width_twips.max(1)))
}

fn resize_column_vector(values: &mut Vec<i32>, index: usize, default: i32) {
    if values.len() <= index {
        values.resize(index + 1, default);
    }
}

fn image_placement_has_non_default_layout_metadata(placement: &StaticImagePlacement) -> bool {
    placement.z_order != 0
        || placement.below_text
        || placement.text_wrap
        || placement.wrap_side != StaticImageWrapSide::Both
        || placement.wrap_margin_left_twips != 0
        || placement.wrap_margin_right_twips != 0
        || placement.wrap_margin_top_twips != 0
        || placement.wrap_margin_bottom_twips != 0
        || placement.horizontal_anchor != StaticShapeHorizontalAnchor::Column
        || placement.vertical_anchor != StaticShapeVerticalAnchor::Paragraph
}

fn passive_picture_placeholder_image(picture: &PictureBuilder) -> StaticImage {
    StaticImage {
        format: ImageFormat::Placeholder,
        bytes: Vec::new(),
        palette: Vec::new(),
        alpha_mask: None,
        tone_adjustment: None,
        vector_commands: Vec::new(),
        width_px: picture.width_px_hint.unwrap_or(1).max(1),
        height_px: picture.height_px_hint.unwrap_or(1).max(1),
        natural_width_px_hint: picture.width_px_hint,
        natural_height_px_hint: picture.height_px_hint,
        display_width_twips: picture.display_width_twips,
        display_height_twips: picture.display_height_twips,
        scale_x_percent: picture.scale_x_percent,
        scale_y_percent: picture.scale_y_percent,
        crop: picture.crop,
        placement: None,
    }
}

fn passive_emf_placeholder_image(picture: &PictureBuilder, emf: &ParsedEmfHeader) -> StaticImage {
    let mut image = passive_picture_placeholder_image(picture);
    if picture.width_px_hint.is_none() {
        image.width_px = emf.width_px.max(1);
        image.natural_width_px_hint = Some(emf.width_px.max(1));
    }
    if picture.height_px_hint.is_none() {
        image.height_px = emf.height_px.max(1);
        image.natural_height_px_hint = Some(emf.height_px.max(1));
    }
    if image.display_width_twips.is_none() {
        image.display_width_twips = emf.frame_width_twips;
    }
    if image.display_height_twips.is_none() {
        image.display_height_twips = emf.frame_height_twips;
    }
    image
}

fn passive_empty_picture_placeholder_image(
    picture: &PictureBuilder,
    fallback_width_twips: Option<i32>,
    fallback_height_twips: Option<i32>,
) -> Option<StaticImage> {
    let fallback_dimensions = match (fallback_width_twips, fallback_height_twips) {
        (Some(width), Some(height)) if width > 0 && height > 0 => Some((width, height)),
        _ => None,
    };
    let has_picture_geometry = picture.display_width_twips.is_some()
        || picture.display_height_twips.is_some()
        || picture.width_px_hint.is_some()
        || picture.height_px_hint.is_some();
    if !has_picture_geometry && fallback_dimensions.is_none() {
        return None;
    }

    let mut image = passive_picture_placeholder_image(picture);
    if let Some((width, height)) = fallback_dimensions {
        image.display_width_twips = image.display_width_twips.or(Some(width));
        image.display_height_twips = image.display_height_twips.or(Some(height));
    }
    Some(image)
}

fn apply_rgb8_picture_color_mode(
    bytes: &mut [u8],
    width_px: u32,
    height_px: u32,
    adjustments: PictureAdjustments,
) -> bool {
    if !adjustments.grayscale
        && !adjustments.bilevel
        && adjustments.brightness_fixed.is_none()
        && adjustments.contrast_fixed.is_none()
    {
        return true;
    }
    let Some(expected_len) = usize::try_from(width_px)
        .ok()
        .and_then(|width| {
            usize::try_from(height_px)
                .ok()
                .and_then(|height| width.checked_mul(height))
        })
        .and_then(|pixels| pixels.checked_mul(3))
    else {
        return false;
    };
    if bytes.len() != expected_len {
        return false;
    }

    for pixel in bytes.chunks_exact_mut(3) {
        apply_picture_adjustments_to_rgb(pixel, adjustments);
    }
    true
}

fn rgb_luminance(red: u8, green: u8, blue: u8) -> u8 {
    ((u32::from(red) * 2_126 + u32::from(green) * 7_152 + u32::from(blue) * 722 + 5_000) / 10_000)
        as u8
}

fn adjust_picture_sample(sample: u8, adjustments: PictureAdjustments) -> u8 {
    let contrast = f64::from(
        adjustments
            .contrast_fixed
            .unwrap_or(65_536)
            .clamp(0, 196_608),
    ) / 65_536.0;
    let brightness = f64::from(
        adjustments
            .brightness_fixed
            .unwrap_or(0)
            .clamp(-32_768, 32_768),
    ) / 32_768.0;
    let adjusted = (f64::from(sample) - 127.5) * contrast
        + 127.5
        + brightness * 255.0 * (contrast + 1.0) / 2.0;
    adjusted.round().clamp(0.0, 255.0) as u8
}

fn apply_jpeg_picture_color_mode_as_rgb8(
    image: &mut StaticImage,
    adjustments: PictureAdjustments,
) -> bool {
    if !adjustments.grayscale
        && !adjustments.bilevel
        && adjustments.brightness_fixed.is_none()
        && adjustments.contrast_fixed.is_none()
    {
        return true;
    }
    let Some(mut rgb) = decode_bounded_jpeg_to_rgb8(
        &image.bytes,
        image.width_px,
        image.height_px,
        image.format,
        MAX_EXACT_JPEG_COLOR_MODE_BYTES,
        MAX_EXACT_JPEG_COLOR_MODE_PIXELS,
    ) else {
        return false;
    };
    for pixel in rgb.chunks_exact_mut(3) {
        apply_picture_adjustments_to_rgb(pixel, adjustments);
    }
    image.format = ImageFormat::Rgb8;
    image.bytes = rgb;
    image.tone_adjustment = None;
    true
}

fn passive_jpeg_tone_adjustment(
    format: ImageFormat,
    adjustments: PictureAdjustments,
) -> Option<ImageToneAdjustment> {
    if !matches!(
        format,
        ImageFormat::Jpeg
            | ImageFormat::JpegInverted
            | ImageFormat::JpegGrayscale
            | ImageFormat::JpegGrayscaleInverted
            | ImageFormat::JpegPassiveGrayscale
            | ImageFormat::JpegCmyk
            | ImageFormat::JpegCmykInverted
    ) {
        return None;
    }
    if adjustments.bilevel
        || (adjustments.brightness_fixed.is_none() && adjustments.contrast_fixed.is_none())
    {
        return None;
    }
    let (low_sample, high_sample) = if matches!(
        format,
        ImageFormat::JpegInverted
            | ImageFormat::JpegGrayscaleInverted
            | ImageFormat::JpegCmykInverted
    ) {
        (255, 0)
    } else {
        (0, 255)
    };
    Some(ImageToneAdjustment {
        decode_low: f32::from(adjust_picture_sample(low_sample, adjustments)) / 255.0,
        decode_high: f32::from(adjust_picture_sample(high_sample, adjustments)) / 255.0,
    })
}

fn apply_picture_adjustments_to_rgb(pixel: &mut [u8], adjustments: PictureAdjustments) {
    pixel[0] = adjust_picture_sample(pixel[0], adjustments);
    pixel[1] = adjust_picture_sample(pixel[1], adjustments);
    pixel[2] = adjust_picture_sample(pixel[2], adjustments);
    if adjustments.grayscale || adjustments.bilevel {
        let gray = rgb_luminance(pixel[0], pixel[1], pixel[2]);
        let value = if adjustments.bilevel {
            if gray >= 128 { 255 } else { 0 }
        } else {
            gray
        };
        pixel[0] = value;
        pixel[1] = value;
        pixel[2] = value;
    }
}

fn apply_picture_adjustments_to_gray(sample: &mut u8, adjustments: PictureAdjustments) {
    *sample = adjust_picture_sample(*sample, adjustments);
    if adjustments.bilevel {
        *sample = if *sample >= 128 { 255 } else { 0 };
    }
}

fn apply_indexed_palette_picture_color_mode(
    palette: &mut [u8],
    adjustments: PictureAdjustments,
) -> bool {
    if !adjustments.grayscale
        && !adjustments.bilevel
        && adjustments.brightness_fixed.is_none()
        && adjustments.contrast_fixed.is_none()
    {
        return true;
    }
    if palette.is_empty() || palette.len() % 3 != 0 {
        return false;
    }

    for entry in palette.chunks_exact_mut(3) {
        apply_picture_adjustments_to_rgb(entry, adjustments);
    }
    true
}

fn apply_png_picture_color_mode(
    bytes: &mut Vec<u8>,
    alpha_mask: &mut Option<StaticImageAlphaMask>,
    width_px: u32,
    height_px: u32,
    format: ImageFormat,
    adjustments: PictureAdjustments,
) -> bool {
    if !adjustments.grayscale
        && !adjustments.bilevel
        && adjustments.brightness_fixed.is_none()
        && adjustments.contrast_fixed.is_none()
    {
        return true;
    }
    let components = match format {
        ImageFormat::Png => 3usize,
        ImageFormat::PngGrayscale => 1usize,
        _ => return false,
    };
    let Some(width) = usize::try_from(width_px).ok() else {
        return false;
    };
    let Some(height) = usize::try_from(height_px).ok() else {
        return false;
    };
    let Some(row_pixels_len) = width.checked_mul(components) else {
        return false;
    };
    let Some(row_len) = row_pixels_len.checked_add(1) else {
        return false;
    };
    let Some(expected_len) = row_len.checked_mul(height) else {
        return false;
    };
    let Some(mut scanlines) = inflate_zlib_png_scanlines(bytes, expected_len) else {
        return false;
    };
    if !unfilter_png_scanlines(&mut scanlines, row_len, components) {
        return false;
    }
    let decoded_alpha = if let Some(mask) = alpha_mask.as_ref() {
        let Some(alpha_row_len) = width.checked_add(1) else {
            return false;
        };
        let Some(alpha_len) = alpha_row_len.checked_mul(height) else {
            return false;
        };
        let Some(mut alpha) = inflate_zlib_png_scanlines(&mask.bytes, alpha_len) else {
            return false;
        };
        if !unfilter_png_scanlines(&mut alpha, alpha_row_len, 1) {
            return false;
        }
        Some((alpha, alpha_row_len))
    } else {
        None
    };

    for row in scanlines.chunks_exact_mut(row_len) {
        let pixels = &mut row[1..];
        match format {
            ImageFormat::Png => {
                for pixel in pixels.chunks_exact_mut(3) {
                    apply_picture_adjustments_to_rgb(pixel, adjustments);
                }
            }
            ImageFormat::PngGrayscale => {
                for sample in pixels {
                    apply_picture_adjustments_to_gray(sample, adjustments);
                }
            }
            _ => return false,
        }
    }

    // Word retains the PNG soft mask through picture color adjustment. Keep
    // fully transparent base samples canonical black so inert RGB cannot vary
    // between decoders, but never flatten opacity into the painted pixels.
    if let Some((alpha, alpha_row_len)) = decoded_alpha {
        for (row, alpha_row) in scanlines
            .chunks_exact_mut(row_len)
            .zip(alpha.chunks_exact(alpha_row_len))
        {
            for (pixel, opacity) in row[1..]
                .chunks_exact_mut(components)
                .zip(alpha_row[1..].iter().copied())
            {
                if opacity == 0 {
                    pixel.fill(0);
                }
            }
        }
    }

    *bytes = miniz_oxide::deflate::compress_to_vec_zlib(&scanlines, 6);
    true
}

fn apply_jpeg_passive_picture_color_mode(
    format: &mut ImageFormat,
    grayscale: bool,
    bilevel: bool,
) -> bool {
    if !grayscale && !bilevel {
        return true;
    }
    *format = match (*format, bilevel) {
        (ImageFormat::Jpeg, false) => ImageFormat::JpegPassiveGrayscale,
        (ImageFormat::Jpeg, true) => ImageFormat::JpegPassiveBilevel,
        (ImageFormat::JpegPassiveGrayscale | ImageFormat::JpegPassiveBilevel, true) => {
            ImageFormat::JpegPassiveBilevel
        }
        (ImageFormat::JpegPassiveGrayscale | ImageFormat::JpegPassiveBilevel, false) => {
            ImageFormat::JpegPassiveGrayscale
        }
        (ImageFormat::JpegCmyk, false) => ImageFormat::JpegCmykPassiveGrayscale,
        (ImageFormat::JpegCmyk, true) => ImageFormat::JpegCmykPassiveBilevel,
        (ImageFormat::JpegCmykPassiveGrayscale | ImageFormat::JpegCmykPassiveBilevel, true) => {
            ImageFormat::JpegCmykPassiveBilevel
        }
        (ImageFormat::JpegCmykPassiveGrayscale | ImageFormat::JpegCmykPassiveBilevel, false) => {
            ImageFormat::JpegCmykPassiveGrayscale
        }
        _ => return false,
    };
    true
}

#[derive(Debug)]
struct ParsedVectorRasterImage {
    width_px: u32,
    height_px: u32,
    format: ImageFormat,
    bytes: Vec<u8>,
    palette: Vec<u8>,
    alpha_mask: Option<StaticImageAlphaMask>,
}

#[derive(Debug, Copy, Clone, PartialEq, Eq)]
enum PassiveSourceRasterTransferMode {
    Copy,
    Invert,
    Mask(Color),
    Solid(Color),
    SourceIgnoring {
        raster_op: u32,
        selected_fill_color: Option<Color>,
        blank_destination: bool,
    },
    SameBoundsBackdropAndIfSolidSource,
    SameBoundsBackdropNorIfSolidSource,
    SameBoundsBackdropOrIfSolidSource,
    SameBoundsBackdropOrNotSourceIfSolidSource,
    SameBoundsBackdropOrPatternOrNotSourceIfSolidSource {
        pattern: Color,
        blank_destination: bool,
    },
    SameBoundsBackdropSourceAndNotDestIfSolidSource,
    SameBoundsBackdropXorIfSolidSource,
}

enum PassiveSourceRasterTransfer {
    Image(ParsedVectorRasterImage),
    Solid(Color),
    SameBoundsBackdropAnd(Color),
    SameBoundsBackdropNor(Color),
    SameBoundsBackdropOr(Color),
    SameBoundsBackdropSourceAndNotDest(Color),
    SameBoundsBackdropXor(Color),
    Noop,
}

enum PassiveSourceRasterCommand {
    Draw(StaticImageVectorCommand),
    DrawMany(Vec<StaticImageVectorCommand>),
    ReduceSameBoundsBackdrop {
        bounds: (f32, f32, f32, f32),
        raster_op: u32,
        selected_fill_color: Option<Color>,
    },
    Noop,
}

fn source_ignoring_passive_source_raster_command(
    bounds: (f32, f32, f32, f32),
    raster_op: u32,
    selected_fill_color: Option<Color>,
    blank_destination: bool,
) -> Option<PassiveSourceRasterCommand> {
    match raster_op {
        WMF_NOTPATCOPY_RASTER_OP => {
            let fill_color = inverted_color(selected_fill_color?);
            Some(passive_source_raster_command(
                bounds.0,
                bounds.1,
                bounds.2,
                bounds.3,
                PassiveSourceRasterTransfer::Solid(fill_color),
            ))
        }
        WMF_PATINVERT_RASTER_OP if selected_fill_color == Some(Color::default()) => {
            Some(PassiveSourceRasterCommand::Noop)
        }
        WMF_PATINVERT_RASTER_OP if blank_destination => {
            let fill_color = inverted_color(selected_fill_color?);
            Some(passive_source_raster_command(
                bounds.0,
                bounds.1,
                bounds.2,
                bounds.3,
                PassiveSourceRasterTransfer::Solid(fill_color),
            ))
        }
        WMF_PATINVERT_RASTER_OP => Some(PassiveSourceRasterCommand::ReduceSameBoundsBackdrop {
            bounds,
            raster_op,
            selected_fill_color,
        }),
        _ => None,
    }
}

